#!/usr/bin/env python3
"""Generate reports/joint_ns_loss_mechanism_report.md from the analysis JSONs."""
import json
import os
import time

BASE = "/workspaces/mvp/testdata/joint_ns_loss_mechanism"
J = json.load(open(os.path.join(BASE, "analytical_gate", "stationary_screen.json")))
A = json.load(open(os.path.join(BASE, "analysis", "analytical_gate_analysis.json")))
MIB = 1024 ** 2
N_GRID = [1, 2, 4, 8, 16]
S_GRID = [262144, 1048576, 4194304, 16777216]
CONDS = ["GOOD", "BAD"]


def cell(cond, n, s):
    return J["conditions"][cond]["cells"]["%d/%d" % (n, s)]


def f(x):
    return "%.2f" % x


L = []
a = L.append
a("# Correlated Loss / Range-Retry Mechanism — Analytical Gate Report")
a("")
a("**Status: `NO_JOINT_N+S_OPPORTUNITY_UNDER_CORRELATED_LOSS`.** The correlated-loss /")
a("range-retry mechanism produces a **material S-retry amplification** under the burst")
a("loss condition, but the concurrency dimension remains **monotone/work-conserving** in")
a("every condition and every predeclared parameter variant. The joint (N*,S*) optimum")
a("therefore does **not** move (N* = 16 in both loss states). The analytical gate fails")
a("condition 1; per the frozen rules no live mechanism gate, no adaptive execution and")
a("no confirmatory protocol were created.")
a("")
a("ANALYTICAL SIMULATION ONLY: no network experiment was run. All numbers are")
a("deterministic simulator output (seeded two-state Markov loss traces), not empirical")
a("evidence.")
a("")
a("Generated: %s" % time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))
a("")
a("## 1. Prior mechanism closures (unchanged)")
a("")
a("- Fixed D2 aria2 win: fixed N=16/S=4 MiB beats fixed aria2 split=16 by 62.4 %")
a("  (30/30 fresh pairs). Not an adaptive result.")
a("- Static rate+RTT S headroom: non-positive at every file size (Stage 0S GO, scaling")
a("  and pivot closed; no state-dependent S optimum).")
a("- Phase-locked pacing joint N+S screen: N*=16 in every regime, S only, no causal")
a("  joint headroom (gate FAIL).")
a("- Live shared FIFO bottleneck/queueing screen: real contention cost, work-conserving,")
a("  no state-dependent N optimum (`NO_LIVE-GROUNDED_JOINT_N+S_OPPORTUNITY`).")
a("- T1/M3: aggregate throughput monotone in N; no live concurrency reversal.")
a("")
a("## 2. Why correlated loss / retry amplification is materially different")
a("")
a("The screened mechanisms so far acted on the *transfer rate* of independent requests.")
a("This mechanism acts on the **request failure path**: a burst-loss interval can stall a")
a("range request past the downloader's 30 s timeout, the failed range is retried from")
a("scratch with its original boundaries, and the wasted work grows with S (a larger")
a("range contains more packets and has a longer transfer window, so it has a larger")
a("exposure to bursts and a smaller timeout margin). That is a different cost channel")
a("from per-response pacing or FIFO queueing, and it is the last mechanism branch")
a("before the mechanism search is closed.")
a("")
a("## 3. Parameter grounding (see `parameter_grounding/parameter_grounding.md`)")
a("")
a("- Clean-state loss 0.4 % (D2 netem, project) / 1 % (project scenarios); severe-state")
a("  time-averaged loss 2.5–7 % (project L1/L4 phases and DQN test conditions).")
a("- Burst dynamics: two-state Gilbert–Elliott model, explicitly grounded in")
a("  NTIA TM-23-565 (model controls; Gilbert's h = 0.5) and Haßlinger–Hohlfeld (MMB")
a("  2008) measured GE parameter ranges; burst-run literature (Paxson 1997; Yajnik et")
a("  al. 1999). The project contains **no** correlated-loss measurements; this is")
a("  recorded explicitly and the burst parameters are swept as a predeclared")
a("  robustness range rather than fitted.")
a("- Frozen retry semantics: 30 s request timeout, 3 attempts, same-range retry,")
a("  ~0.1 s retry gap, in-flight immutability; rate R = 640 KiB/s primary (the D2")
a("  initial rate, the documented regime where the timeout actually triggered range")
a("  retries); per-request overhead h = 0.088 s (calibrated project simulator);")
a("  MSS = 1448 B (live-study MTU 1500).")
a("")
a("## 4. Analytical model")
a("")
a("Deterministic event-driven simulator (`tools/loss_sim.py`): time-indexed two-state")
a("Markov loss process (G: loss p_G, mean sojourn T_G; B: loss p_B, mean sojourn T_B);")
a("one contiguous range per worker; per-response pacing at R; during B the connection")
a("stalls and recovers after the TCP RTO backoff for the burst duration; during G it")
a("progresses at R(1-p_G). Frozen retry semantics as above. F = 512 MiB;")
a("N ∈ {1,2,4,8,16}; S ∈ {256K,1M,4M,16M}; 10 seeds per cell; identical seed set across")
a("cells; viability rule: a cell is viable if ≥ 50 % of seeds complete.")
a("")
a("Conditions: **GOOD** = T_B = 0.15 s (time-averaged loss 0.42 %); **BAD** = T_B = 2.0 s")
a("(time-averaged loss 4.6 %); p_G = 0.4 %, p_B = 0.5, T_G = 20 s in both.")
a("")
a("## 5. Stationary N results")
a("")
a("| condition | N=1 | N=2 | N=4 | N=8 | N=16 | N* | monotone |")
a("|---|---|---|---|---|---|---|---|")
for cond in CONDS:
    n = A["conditions"][cond]["N"]
    vals = [n[str(x)]["min_completion_s"] for x in N_GRID]
    mono = all(vals[i] >= vals[i + 1] - 1e-9 for i in range(len(vals) - 1))
    a("| %s | %s | %d | %s |" % (cond, " | ".join("%.0f" % v for v in vals), 16, "yes" if mono else "no"))
a("")
a("The completion is monotone decreasing in N in both conditions (ratio ≈ N per")
a("doubling), i.e. the N dimension is work-conserving. Loss-recovery overhead (stall")
a("time) and burst-event counts grow with the download duration, not with N; the")
a("per-request burst exposure is N-independent. **N\\* = 16 in every condition and in")
a("all 9 predeclared robustness variants.**")
a("")
a("## 6. Stationary S results and the range-retry mechanism check")
a("")
a("BAD condition, aggregated over N and seeds:")
a("")
a("| S | requests/download | packets/request | per-attempt failure rate | retries/download | retry bytes/download | download abort rate |")
a("|---|---|---|---|---|---|---|")
for s in S_GRID:
    m = A["conditions"]["BAD"]["S_retry"][str(s)]
    a("| %s | %d | %d | %.4f | %.1f | %.1f MiB | %.2f |" % (
        "%dK" % (s // 1024) if s < MIB else "%dM" % (s // MIB), m["requests_per_download"],
        m["packets_per_request"], m["per_attempt_failure_rate"], m["retries_per_download"],
        m["retry_bytes_per_download_MiB"], m["download_abort_rate"]))
a("")
a("The required qualitative pattern (larger S → higher failed-range exposure → larger")
a("retry penalty) **is present in BAD**: the failure exposure appears at S = 16 MiB")
a("(32.7 % per-attempt failure rate, 10.6 retries and 169 MiB re-downloaded per")
a("download, 48 % of downloads aborting after exhausting the 3-attempt retry limit).")
a("In GOOD no S fails (0.4 % loss with 0.15 s bursts is recovered well inside the")
a("timeout margin), so the S exposure is a *loss-state-dependent* effect, not a")
a("generic S cost.")
a("")
a("## 7. Joint-optimum result")
a("")
a("| condition | optimum | completion | second best | margin |")
a("|---|---|---|---|---|")
for cond in CONDS:
    o = J["conditions"][cond]["optimum"]
    a("| %s | (N=%d, S=%s) | %.1f s | (%s) | %+.1f%% |" % (
        cond, o["N"], "%dM" % (o["S"] // MIB) if o["S"] >= MIB else "%dK" % (o["S"] // 1024),
        o["completion"], o["second_key"], 100 * o["margin"]))
a("")
a("Materiality (completion penalty at N=16 when the other state's optimal S is used):")
a("")
a("- BAD using the GOOD optimum S=16M: **+36.3 %** (81.8 s vs 60.0 s) → material.")
a("- GOOD using the BAD optimum S=4M: **+0.8 %** (53.0 s vs 52.6 s) → immaterial.")
a("")
a("So the **S component moves materially** (S* = 16M in GOOD → 4M in BAD), but the")
a("**N component does not move at all** (N* = 16 in both). By the task's own rule this")
a("is a **single-dimensional (S-only) opportunity, not a joint N+S opportunity**.")
a("")
a("## 8. Live mechanism gate")
a("")
a("**NOT REACHED.** The analytical gate requires condition 1 (N* differs between loss")
a("states) to hold before any live execution; it fails, so no live mechanism gate was")
a("run and no live loss-shaping experiment was performed.")
a("")
a("## 9. Causal adaptive result")
a("")
a("**NOT REACHED.** Conditions 4–6 (within-download transition, causal detection,")
a("positive causal joint headroom) were not evaluated because conditions 1–3 failed.")
a("No adaptive controller was implemented or run; the frozen starting configuration")
a("(4, 4 MiB) and one-switch semantics were never exercised.")
a("")
a("## 10. aria2 result")
a("")
a("**NOT REACHED.** aria2 was reserved for the practical comparison after the causal")
a("gates; its frozen configuration was not touched.")
a("")
a("## 11. Stationary controls")
a("")
a("The two stationary loss conditions (GOOD/BAD) are themselves the stationary")
a("controls for this mechanism. Neither shows a state-dependent N optimum, so there")
a("is no adaptive advantage to control for; the stationary control requirement is")
a("moot because the joint gate never passed.")
a("")
a("## 12. Causal/oracle headroom")
a("")
a("**NOT MEASURED** (no adaptive runs). The structural reason is explicit: under")
a("per-response pacing the per-request burst exposure and the aggregate progress are")
a("N-independent, so the only state-dependent dimension is S — and an S-only")
a("adaptation is not a joint N+S result.")
a("")
a("## 13. Failure modes and robustness")
a("")
a("- **Threshold-like S effect.** The failure exposure appears only at S = 16 MiB under")
a("  BAD; S ≤ 4 MiB never fails. The S* movement is therefore driven by one grid point.")
a("- **Variant dependence.** Across the 9 predeclared variants the S* moves between")
a("  conditions in 4/9 cases (primary, T_G=10 s, g=0.25, g=0.5) and not in the others")
a("  (T_B=1 s/p_B=1.0, T_B=5 s, T_G=60 s, R=1250 KiB/s, R=2500 KiB/s). At faster base")
a("  rates the timeout margin is large enough that no S fails — the S-retry")
a("  amplification is **rate-conditional**.")
a("- **Structural N insufficiency.** N* = 16 in 9/9 variants and both conditions;")
a("  monotone decreasing completion in 9/9. This matches the project's live T1 result")
a("  and the live shared-bottleneck screen: no live-grounded concurrency cost exists.")
a("- **Model abstractions.** The B-state stall abstraction and the constant rate are")
a("  the main modelling choices; both were predeclared with sensitivity axes (g, R)")
a("  and the conclusion (no N movement) holds across all of them.")
a("- **No result shopping:** parameters, grid, seeds, conditions, viability rule and")
a("  robustness variants were frozen in `parameter_grounding/` before the runs; failed")
a("  (aborted) downloads are recorded, not discarded.")
a("")
a("## 14. Exact claim supported")
a("")
a("**Within the frozen analytical model and its predeclared parameter ranges:**")
a("correlated burst loss combined with the downloader's range-retry semantics creates a")
a("material, loss-state-dependent **chunk-size** effect (S = 16 MiB is fragile under")
a("burst loss: 32.7 % per-attempt failure, 48 % download aborts, +36.3 % completion")
a("penalty), but **no loss-state-dependent concurrency effect**: N* = 16 in every loss")
a("state and every parameter variant. There is therefore **no joint N+S adaptation")
a("opportunity under this mechanism**. Per the task's stop condition, the mechanism")
a("search is closed; no live/adaptive execution and no confirmatory protocol follow.")
a("The project's defensible competitive result remains the **fixed N=16, S=4 MiB D2")
a("aria2 win (62.4 %)**, unchanged.")
a("")
a("## 15. Figures")
a("")
for fn, cap in [
    ("fig1_completion_vs_N.png", "completion vs N by loss condition"),
    ("fig2_completion_vs_S.png", "completion vs S by loss condition (N=16)"),
    ("fig3_surface_GOOD.png", "T(N,S) surface, GOOD"),
    ("fig4_surface_BAD.png", "T(N,S) surface, BAD"),
    ("fig5_optimum_movement.png", "the key figure: optimum movement + materiality"),
    ("fig6_failure_vs_S.png", "failure/abort exposure vs S"),
    ("fig7_retry_cost_vs_S.png", "retries and retry bytes vs S"),
    ("fig8_robustness.png", "optima across the 9 predeclared variants"),
]:
    a("- `figures/%s` — %s" % (fn, cap))
a("")
a("## 16. Artifacts")
a("")
a("- `parameter_grounding/parameter_grounding.md`; `analytical_gate/stationary_screen.json`,")
a("  `analytical_gate/robustness_sweep.json`; `analysis/analytical_gate_analysis.json`;")
a("  `figures/fig1..fig8`; `tools/loss_sim.py`, `tools/run_screen.py`,")
a("  `tools/run_robustness.py`, `tools/analyze_gate.py`, `tools/make_figures.py`,")
a("  `tools/make_report.py`; `manifest/manifest.json`.")
a("")
open(os.path.join(BASE, "reports", "joint_ns_loss_mechanism_report.md"), "w").write("\n".join(L) + "\n")
